async () => { const mg = window.MinigameFramework.currentMinigame; const C = mg.container; const sleep = ms => new Promise(r=>setTimeout(r,ms)); const start = C.querySelector('.tri-start'); if (start) start.click(); await sleep(120);
const plan = [['e16_offer','verdict','report',['insider_offer','secrecy_or_bypass']],['e16_shared_login_req','verdict','report',['borrowed_authority']],['e16_mfa_storm','action','deny_report',['unrequested_mfa_push']],['e16_leaver_favour','verdict','report',['secrecy_or_bypass']],['e16_it_approve','verdict','report',['secrecy_or_bypass','lookalike_domain']],['e16_genuine_lockout','action','verify_callback',['none']]];
for (const [id,how,act,chips] of plan) { const row = C.querySelector('.mail-row[data-id="'+id+'"]'); if (!row) return { fail: 'row '+id }; row.click(); await sleep(70);
 const vb = how === 'action' ? C.querySelector('.tri-verdict[data-action="'+act+'"]') : C.querySelector('.tri-verdict[data-verdict="'+act+'"]'); if (!vb) return { fail: 'verdict '+id }; vb.click(); await sleep(70);
 for (const ch of chips) { const inp = C.querySelector('input[data-chip="'+ch+'"]'); if (inp && !inp.checked) inp.click(); }
 const conf = C.querySelector('.tri-confirm'); if (!conf) return { fail: 'confirm '+id }; conf.click(); await sleep(100);
 const nx = C.querySelector('.tri-next'); if (nx) { nx.click(); await sleep(100); } }
const s = mg.getTestState(); return s.triage.step === 'result'; }

async () => {
  const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const q = s => { const m = window.MinigameFramework.currentMinigame; return m && m.container && m.container.querySelector(s); };
  const end = Date.now() + 60000;
  while (Date.now() < end) { const f = q('.tri-finish'); if (f && !f.disabled) { f.click(); return true; } await sleep(150); }
  return false;
}
